cd /tmp && python3 -I -c "
import sys, zipfile, tarfile, gzip, io, pickletools
for f in ['sample_10.npy','sample_11.tgz','sample_23.pth','sample_24.gz','sample_25.tar','sample_26.npz','sample_30.zip']:
    p = '/app/samples/'+f
    data = open(p,'rb').read()
    print('=================', f, len(data), repr(data[:64]))
    if zipfile.is_zipfile(io.BytesIO(data)):
        zf = zipfile.ZipFile(io.BytesIO(data))
        for zi in zf.infolist():
            print('  zip member', zi.filename, zi.file_size, zi.compress_type)
            d = zf.read(zi)
            print('    ', repr(d[:80]))
    elif data[:2] == b'\x1f\x8b':
        try:
            d = gzip.decompress(data)
            print('  gz decompressed', len(d), repr(d[:80]))
            try:
                tf = tarfile.open(fileobj=io.BytesIO(d))
                for m in tf.getmembers():
                    print('  tar member', m.name, m.size, m.type)
                    if m.isfile():
                        dd = tf.extractfile(m).read()
                        print('     ', repr(dd[:80]))
            except Exception as e:
                print('  not tar', e)
        except Exception as e:
            print('  gz err', e)
    else:
        try:
            tf = tarfile.open(fileobj=io.BytesIO(data))
            for m in tf.getmembers():
                print('  tar member', m.name, m.size, m.type)
                if m.isfile():
                    dd = tf.extractfile(m).read()
                    print('     ', repr(dd[:80]))
        except Exception as e:
            print('  not tar', e)
"

