arguments.command:
cd /tmp && python3 -I -c "
import sys
sys.path.insert(0,'/app')
from modelgate.tfproto import saved_model_pb2
for d in ['sample_12','sample_13','sample_21','sample_27']:
    print('=================', d)
    sm = saved_model_pb2.SavedModel()
    sm.ParseFromString(open('/app/samples/'+d+'/saved_model.pb','rb').read())
    print('meta_graphs:', len(sm.meta_graphs))
    for i, mg in enumerate(sm.meta_graphs):
        print(' meta_graph', i, 'tags', list(mg.meta_info_def.tags))
        print('  signature_def keys:', list(mg.signature_def.keys()))
        g = mg.graph_def
        print('  nodes:', [(n.name, n.op) for n in g.node])
        for fn in g.library.function:
            print('  function', fn.signature.name, [(n.name, n.op) for n in fn.node_def])
            for n in fn.node_def:
                for k, v in n.attr.items():
                    if v.HasField('func'):
                        print('    node', n.name, 'attr', k, 'func ->', v.func.name)
                    if v.list.func:
                        print('    node', n.name, 'attr', k, 'func list ->', [f.name for f in v.list.func])
        for n in g.node:
            for k, v in n.attr.items():
                if v.HasField('func'):
                    print('  node', n.name, 'attr', k, 'func ->', v.func.name)
                if v.list.func:
                    print('  node', n.name, 'attr', k, 'func list ->', [f.name for f in v.list.func])
"

