def _header_has_object(text):
    """True if the npy descr names the object dtype (so numpy.load unpickles)."""
    i = text.find("descr")
    j = text.find("fortran_order")
    seg = text[i:j] if 0 <= i < j else text
    return any(tok in seg for tok in ("|O", "'O'", '"O"', "|O8", "'O8'", '"O8"'))

